// Canvas 01 / Contract v1.0. No secrets, outbound HTTP calls or providers here.
const envelope = $input.first().json;
let body = envelope?.body;
const errors = [];
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (_) { body = null; }
}
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return [{json:{valid_request:false,validation_errors:['body_must_be_json_object']}}];
}
let size = 0;
try { size = JSON.stringify(body).length; } catch (_) {
  return [{json:{valid_request:false,validation_errors:['body_not_serializable']}}];
}
if (size > 16000) {
  return [{json:{valid_request:false,validation_errors:['body_exceeds_16k_limit']}}];
}
const t = (value, max) => typeof value === 'string' ? value.trim().slice(0,max) : '';
const source = t(body.source ?? body.lead_source,65).toLowerCase();
const upstreamKey = t(body.event_key ?? body.event_id ?? body.submission_id,161);
if (!/^[a-z0-9_.-]{1,64}$/.test(source)) errors.push('invalid_or_missing_source');
if (!/^[A-Za-z0-9:._-]{1,160}$/.test(upstreamKey)) errors.push('invalid_or_missing_event_key');
if (errors.length) return [{json:{valid_request:false,validation_errors:errors}}];

const firstName = t(body.first_name ?? body.name,120).replace(/[\u0000-\u001F]/g,' ');
const rawEmail = typeof (body.email ?? body.email_address) === 'string'
  ? (body.email ?? body.email_address).trim().toLowerCase() : '';
let email = rawEmail;
let phone = typeof (body.phone_e164 ?? body.phone ?? body.mobile) === 'string'
  ? (body.phone_e164 ?? body.phone ?? body.mobile).trim().replace(/[\s().-]/g,'') : '';
if (/^03\d{9}$/.test(phone)) phone = '+92' + phone.slice(1);
else if (/^92\d{10}$/.test(phone)) phone = '+' + phone;

const identityProblems = [];
if (rawEmail && (rawEmail.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(rawEmail)))
  identityProblems.push('invalid_email');
if (phone && !/^\+[1-9]\d{7,14}$/.test(phone)) identityProblems.push('invalid_phone');
if (!rawEmail && !phone) identityProblems.push('missing_email_and_phone');
// Invalid supplied identity forces a durable quarantine through accept_lead().
if (identityProblems.length) { email = null; phone = null; }

const safePayload = {
  source_event_key: upstreamKey,
  sms_consent: body.sms_consent === true,
  email_consent: body.email_consent === true,
  message: t(body.message ?? body.inquiry ?? body.requirements,2500),
  campaign: t(body.campaign,180),
  utm_source: t(body.utm_source,180),
  utm_medium: t(body.utm_medium,180),
  utm_campaign: t(body.utm_campaign,180),
  validation_errors: identityProblems
};
return [{json:{
  valid_request:true,
  schema_version:'1.0',
  // Prefix source because leads.event_key is globally unique across sources.
  event_key:source+':'+upstreamKey,
  source,
  first_name:firstName || null,
  email:email || null,
  phone_e164:phone || null,
  raw_payload:safePayload,
  t_received:new Date().toISOString(),
  identity_will_quarantine:identityProblems.length>0
}}];

const result = $input.first().json.intake_result;
if (!result || typeof result !== 'object' || result.schema_version !== '1.0'
    || !['accepted','repeat','duplicate','quarantined'].includes(result.outcome)) {
  throw new Error('Canvas 01 returned an invalid database contract response');
}
return [{json:{
  ok: result.ok === true,
  schema_version:'1.0',
  outcome:result.outcome,
  lead_id:result.lead_id ?? null,
  contact_id:result.contact_id ?? null,
  event_key:result.event_key ?? null,
  assigned_rep_id:result.assigned_rep_id ?? null,
  assignment_outcome:result.assignment_outcome ?? null,
  ack_status:result.ack_status ?? null,
  queued_handoffs:result.queued_handoffs ?? 0,
  downstream_execution:result.downstream_execution ?? 'not_triggered',
  reason:result.reason ?? null
}}];
